import zipfile
from xml.etree import ElementTree as ET

def local(tag):
    return tag.split('}')[-1]

z = zipfile.ZipFile('budget.xlsx')
root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))

print('Cells with formulas (f elements):')
for c in root.iter():
    if local(c.tag) == 'c':
        f = c.find('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}f')
        if f is None:
            for child in c:
                if local(child.tag) == 'f':
                    f = child
                    break
        if f is not None:
            print(' ', c.get('r'), '=>', f.text)

# Sum all numeric expense line items in column C (rows 11-22) and income in column B (rows 4-7)
nums = {}
for c in root.iter():
    if local(c.tag) != 'c':
        continue
    ref = c.get('r')
    v = None
    for child in c:
        if local(child.tag) == 'v':
            v = child.text
    if v is not None and c.get('t') != 's':
        try:
            nums[ref] = float(v)
        except ValueError:
            pass

expense_items = [nums[r] for r in sorted(nums) if r[0] == 'C' and 11 <= int(r[1:]) <= 22]
income_items  = [nums[r] for r in sorted(nums) if r[0] == 'B' and 4 <= int(r[1:]) <= 7]
print('Income items:', income_items, 'sum =', sum(income_items))
print('Expense items:', expense_items, 'sum =', sum(expense_items))
